POINTS HISTORY
Points
Progress over time

{% set chart_x = 90 %}
{% set chart_y = 250 %}
{% set chart_w = 850 %}
{% set chart_h = 300 %}
{% set history_len = point_history|length %}
{% set label_step = ((history_len - 1) // 5) if history_len > 1 else 1 %}

{% set first_time = point_history[0].timestamp if history_len > 0 else 0 %}
{% set last_time = point_history[-1].timestamp if history_len > 0 else 1 %}
{% set time_span = last_time - first_time %}

{% for tick in point_ticks %}
  {% set gy = chart_y + chart_h - ((tick / point_max) * chart_h if point_max > 0 else 0) %}

  {{ tick }}
{% endfor %}

{# The plotted X coordinate is still based on the real timestamp.
   Axis labels are independent: the renderer provides the start date, each month boundary, and the end date. #}
{% for tick in time_ticks %}
  {% set tx = chart_x + tick.position * chart_w %}

  {{ tick.label }}
{% endfor %}

{% if history_len > 0 %}
  {% set ns = namespace(area='M ' ~ chart_x ~ ' ' ~ (chart_y + chart_h), line='') %}
  {% for item in point_history %}
    {% set px = chart_x + (((item.timestamp - first_time) / time_span) * chart_w if time_span > 0 else 0) %}
    {% set py = chart_y + chart_h - ((item.points / point_max) * chart_h if point_max > 0 else 0) %}
    {% if loop.first %}
      {% set ns.line = 'M ' ~ px ~ ' ' ~ py %}
      {% set ns.area = ns.area ~ ' L ' ~ px ~ ' ' ~ py %}
    {% else %}
      {% set ns.line = ns.line ~ ' H ' ~ px ~ ' V ' ~ py %}
      {% set ns.area = ns.area ~ ' H ' ~ px ~ ' V ' ~ py %}
    {% endif %}
  {% endfor %}
  {% set last_px = chart_x + chart_w %}
  {% set ns.area = ns.area ~ ' L ' ~ last_px ~ ' ' ~ (chart_y + chart_h) ~ ' Z' %}


  {% for item in point_history %}
    {% if loop.first or loop.last %}
      {% set px = chart_x + (((item.timestamp - first_time) / time_span) * chart_w if time_span > 0 else 0) %}
      {% set py = chart_y + chart_h - ((item.points / point_max) * chart_h if point_max > 0 else 0) %}

    {% endif %}
  {% endfor %}
{% endif %}



MAP ACTIVITY
Map activity
Last 21 weeks

{% set grid_x = 90 %}
{% set grid_y = 690 %}
{% set square = activity_square %}
{% set step = activity_step %}

{% for day in activity_days %}
  {{ day }}
{% endfor %}

{% for week in activity_weeks %}
  {% set wx = grid_x + loop.index0 * step %}
  {{ week.label }}
  {% for day in week.days %}
    {% if day.count == 0 %}{% set level = 0 %}
    {% elif day.count <= 2 %}{% set level = 1 %}
    {% elif day.count <= 5 %}{% set level = 2 %}
    {% else %}{% set level = 3 %}{% endif %}

  {% endfor %}
{% endfor %}

{% set legend_x = grid_x %}
{% set legend_y = grid_y + 7 * step + 25 %}
finishes / day
{% for value in activity_legend %}
  {% set lx = legend_x + 86 + loop.index0 * 58 %}

  {{ value.label }}
{% endfor %}
